const bn = p => p.split("/").pop();
function prompt(t){ return "You are reviewing existing grammar tips for the "+t.lang+" deck against the Tip Clarity Standard (format AND judgment in one pass). Read the batch from \`"+t.in+"\` — an array of {id, target, english, tip}. For EACH tip, either return it UNCHANGED (if it already complies) or fix it minimally to comply. Output a JSON array of {id, tip} with the SAME ids and count, WRITE it to \`"+t.out+"\` with the Write tool, return {out, reviewed, changed}.\\n\\nTHE STANDARD:\\n"+t.rules; }
const SCHEMA={type:"object",additionalProperties:false,properties:{out:{type:"string"},reviewed:{type:"number"},changed:{type:"number"}},required:["out","reviewed"]};
log("Tip Clarity Tier 2: "+TASKS.length+" batches across 10 languages.");
const results = await parallel(TASKS.map(t => () => agent(prompt(t), { label: t.lang+"/"+bn(t.out), phase: "Review & fix", agentType: "general-purpose", schema: SCHEMA })));
const byLang={};
for(let i=0;i<TASKS.length;i++){const t=TASKS[i],r=results[i];const L=(byLang[t.lang]=byLang[t.lang]||{ok:0,failed:0,changed:0});if(r){L.ok++;L.changed+=r.changed||0;}else L.failed++;}
return { totalBatches: TASKS.length, completed: results.filter(Boolean).length, byLang };
